html:
{%- set campus_display_name = frappe.db.get_value("Campus", doc.campus, "campus_name") if doc.campus else (doc.campus or "Institution of Legal Education") -%}
{%- set campus_logo_path = frappe.db.get_value("Campus", doc.campus, "logo") if doc.campus else None -%}
{%- set dob = frappe.utils.formatdate(frappe.db.get_value("Applicant", doc.applicant_id, "date_of_birth")) -%}
{%- set father_name = frappe.db.get_value("Applicant", doc.applicant_id, "father_name") -%}
{%- set mother_name = frappe.db.get_value("Applicant", doc.applicant_id, "mother_name") -%}
{%- set issue_date = frappe.utils.formatdate(frappe.utils.nowdate()) -%}

{%- set _site = frappe.utils.get_url() -%}

{#- Logic for Live Image Rendering -#}
{%- set _logo_src = '' -%}
{%- if campus_logo_path -%}
    {%- set _lb64 = get_file_b64(campus_logo_path) -%}
    {%- if _lb64 -%}
        {%- set _lext = (campus_logo_path.split('.')[-1] | lower) -%}
        {%- set _lmime = 'image/jpeg' if _lext in ['jpg','jpeg'] else ('image/png' if _lext == 'png' else 'image/svg+xml') -%}
        {%- set _logo_src = 'data:' ~ _lmime ~ ';base64,' ~ _lb64 -%}
    {%- else -%}{%- set _logo_src = _site ~ campus_logo_path -%}{%- endif -%}
{%- endif -%}

<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8"/>
<style>
    @page { size: A4; margin: 10mm; }
    html, body { margin: 0 !important; padding: 0 !important; background: #fff !important; }

    body {
        font-family: "Times New Roman", Times, serif;
        font-size: 13px;
        color: #000;
        line-height: 1.4;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }

    /* Strict Single Page Layout */
    .card-page {
        width: 100%;
        height: 275mm; /* Fixed A4 usable height */
        margin: 0 auto;
        border: 1.5px solid #555;
        overflow: hidden;
        background: #fff;
        position: relative;
    }

    /* wkhtmltopdf Table System */
    table { width: 100%; border-collapse: collapse; table-layout: fixed; }
    td { vertical-align: top; }

    /* Header Fix */
    .header-table { background: #7b1c1c !important; border-bottom: 3px solid #5a0e0e; }
    .univ-name { 
        font-size: 21px; 
        font-weight: bold; 
        font-family: Arial, sans-serif; 
        color: #ffffff !important; 
        text-transform: none; 
        letter-spacing: 1.2px; 
        line-height: 1.2;
    }
    .univ-sub { 
        font-size: 11px; 
        font-family: Arial, sans-serif; 
        color: #ffffff !important; 
        opacity: 0.85; 
        letter-spacing: 2.5px; 
        margin-top: 3px;
    }

    .title-banner {
        background: #f8f8f8 !important;
        text-align: center;
        padding: 12px;
        border-bottom: 1.5px solid #bbb;
    }
    .t1 { font-size: 15px; font-weight: bold; font-family: Arial, sans-serif; color: #7b1c1c; }
    .t2 { font-size: 13px; font-family: Arial, sans-serif; color: #444; margin-top: 4px; font-weight: bold; }

    .content-wrap { padding: 15px 20px; }

    .section-head {
        font-family: Arial, sans-serif;
        font-size: 13px;
        font-weight: bold;
        color: #7b1c1c;
        border-bottom: 1.5px solid #7b1c1c;
        padding-bottom: 4px;
        margin-bottom: 10px;
        margin-top: 10px;
    }

    .info-box { border: 1.5px solid #bbb; margin-bottom: 15px; border-radius: 2px; }
    .info-tbl td { padding: 6px 10px; font-size: 13px; vertical-align: middle; border-bottom: 1px solid #ddd; }
    .info-tbl tr:last-child td { border-bottom: none; }
    .info-tbl td.lb { font-weight: bold; font-family: Arial, sans-serif; width: 35%; color: #000; }
    .info-tbl td.sp { width: 15px; font-weight: bold; text-align: center; }
    .info-tbl td.vl { font-family: "Times New Roman", Times, serif; font-weight: bold; }

    .results-table { border: 1.5px solid #bbb; margin-top: 10px; }
    .results-table th { background: #f4f4f4 !important; font-family: Arial, sans-serif; font-size: 12px; font-weight: bold; text-align: left; padding: 8px 12px; border: 1px solid #bbb; }
    .results-table td { padding: 10px 12px; font-size: 13px; border: 1px solid #bbb; }
    .score-cell { font-weight: bold; font-size: 14px; }

    .disclaimer {
        margin-top: 20px;
        padding: 12px;
        border: 1px solid #ddd;
        font-family: Arial, sans-serif;
        font-size: 11.5px;
        line-height: 1.5;
        color: #333;
    }

    /* Footer Table Fix */
    .footer-table { 
        margin-top: 25px; 
        border-top: 1px solid #ddd; 
        padding-top: 10px; 
        font-family: Arial, sans-serif; 
        font-size: 9.5px; 
        color: #555;
    }
</style>
</head>
<body>

<div class="card-page">
    <!-- HEADER -->
    <table class="header-table">
        <tr>
            <td style="width: 100px; padding: 10px 18px;">
                <div style="background: #fff; width: 74px; height: 74px; border-radius: 3px; overflow: hidden; text-align: center;">
                    {% if _logo_src %}<img src="{{ _logo_src }}" style="width: 70px; height: 70px; object-fit: contain; margin-top: 2px;">
                    {% else %}<div style="line-height:74px; color:#7b1c1c; font-weight:bold;">LOGO</div>{% endif %}
                </div>
            </td>
            <td style="text-align: center; vertical-align: middle; padding: 10px 0;">
                <div class="univ-name">{{ campus_display_name }}</div>
                <div class="univ-sub">Office of Admissions &middot; Eligibility Cell</div>
            </td>
            <td style="width: 100px;"></td> <!-- Spacer for balance -->
        </tr>
    </table>

    <div class="title-banner">
        <div class="t1">Eligibility Result Mark Sheet</div>
        <div class="t2">Academic Year: {{ doc.academic_year or "—" }} &middot; Admission Cycle: {{ doc.admission_cycle or "—" }}</div>
    </div>

    <div class="content-wrap">
        <div class="section-head">Candidate Details</div>
        <div class="info-box">
            <table class="info-tbl">
                <tr><td class="lb">Candidate Name</td><td class="sp">:</td><td class="vl">{{ doc.candidate_name or "—" }}</td></tr>
                <tr><td class="lb">Application Number</td><td class="sp">:</td><td class="vl">{{ doc.applicant_id or "—" }}</td></tr>
                <tr><td class="lb">Date of Birth</td><td class="sp">:</td><td class="vl">{{ dob or "—" }}</td></tr>
                <tr><td class="lb">Gender</td><td class="sp">:</td><td class="vl">{{ doc.gender or "—" }}</td></tr>
                <tr><td class="lb">Father's Name</td><td class="sp">:</td><td class="vl">{{ father_name or "—" }}</td></tr>
                <tr><td class="lb">Mother's Name</td><td class="sp">:</td><td class="vl">{{ mother_name or "—" }}</td></tr>
            </table>
        </div>

        <div class="section-head">Programme Details</div>
        <div class="info-box">
            <table class="info-tbl">
                <tr><td class="lb">Programme</td><td class="sp">:</td><td class="vl">{{ doc.program or "—" }}</td></tr>
                <tr><td class="lb">Campus</td><td class="sp">:</td><td class="vl">{{ doc.campus or "—" }}</td></tr>
            </table>
        </div>

        <div class="section-head">Assessment Result</div>
        <table class="results-table">
            <thead>
                <tr>
                    <th style="width: 50%;">Assessment Component</th>
                    <th style="width: 25%;">Maximum Marks</th>
                    <th style="width: 25%;">Marks Obtained</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td>Entrance Test Score</td>
                    <td>100</td>
                    <td class="score-cell">{{ doc.entrance_test_score or 0 }}</td>
                </tr>
                <tr>
                    <td>Interview Assessment Score</td>
                    <td>100</td>
                    <td class="score-cell">{{ doc.interview_score or 0 }}</td>
                </tr>
                <tr style="background: #f9f9f9 !important;">
                    <td colspan="2" style="text-align: right; font-weight: bold; font-family: Arial, sans-serif; font-size: 12px;">Result Status</td>
                    <td style="font-weight: bold; font-family: Arial, sans-serif;">{{ doc.result_status or "—" }}</td>
                </tr>
            </tbody>
        </table>

        <div class="disclaimer">
            <strong>Important:</strong> This document is a system-generated mark sheet. 
            It reflects the eligibility assessment based on the scores obtained by the candidate. 
            Final admission is subject to verification of original documents and fulfillment of all criteria. 
            Errors and omissions are excepted.
        </div>

        <table class="footer-table">
            <tr>
                <td style="text-align: left;">
                    Reference: <strong>{{ doc.name }}</strong><br>
                    Generated on: <strong>{{ issue_date }}</strong><br>
                    Source Type: {{ doc.source_type or "—" }}
                </td>
                <td style="text-align: right; vertical-align: bottom;">
                    Authorized Signatory<br>
                    (Digitally Verified Document)
                </td>
            </tr>
        </table>

        <div style="text-align: center; margin-top: 20px; color: #aaa; font-size: 10px;">
            ********************
        </div>
    </div>
</div>

</body>
</html>
